-- raymath bindings (generated by tools/gen_raymath.py): no window required.
local T = ...
local r = T.raylib

local function near(desc, got, expected) T.assert_approx(desc, got, expected, 1e-5) end

-- Scalar helpers
near("Clamp high", r.Clamp(5, 0, 3), 3)
near("Clamp low", r.Clamp(-1, 0, 3), 0)
near("Lerp", r.Lerp(0, 10, 0.25), 2.5)
near("Normalize", r.Normalize(5, 0, 10), 0.5)
near("Remap", r.Remap(5, 0, 10, 100, 200), 150)
near("Wrap", r.Wrap(11, 0, 10), 1)
T.assert_true ("FloatEquals true", r.FloatEquals(1.0, 1.0))
T.assert_false("FloatEquals false", r.FloatEquals(1.0, 2.0))

-- Vector2
local v = r.Vector2Add({x = 1, y = 2}, {x = 3, y = 4})
near("Vector2Add x", v.x, 4); near("Vector2Add y", v.y, 6)
near("Vector2Length", r.Vector2Length({x = 3, y = 4}), 5)
near("Vector2DotProduct", r.Vector2DotProduct({x = 1, y = 2}, {x = 3, y = 4}), 11)
local z = r.Vector2Zero(); near("Vector2Zero", z.x + z.y, 0)
local one = r.Vector2One(); near("Vector2One", one.x + one.y, 2)
local n = r.Vector2Normalize({x = 0, y = 5}); near("Vector2Normalize y", n.y, 1)
T.assert_true("Vector2Equals", r.Vector2Equals({x = 1, y = 1}, {x = 1, y = 1}))
local rot = r.Vector2Rotate({x = 1, y = 0}, math.pi / 2); near("Vector2Rotate x", rot.x, 0); near("Vector2Rotate y", rot.y, 1)

-- Vector3
near("Vector3Length", r.Vector3Length({x = 1, y = 2, z = 2}), 3)
local cp = r.Vector3CrossProduct({x = 1, y = 0, z = 0}, {x = 0, y = 1, z = 0})
near("Vector3CrossProduct z", cp.z, 1)
local sc = r.Vector3Scale({x = 1, y = 2, z = 3}, 2); near("Vector3Scale z", sc.z, 6)
local a, b = r.Vector3OrthoNormalize({x = 1, y = 0, z = 0}, {x = 1, y = 1, z = 0})
near("Vector3OrthoNormalize v1.x", a.x, 1); near("Vector3OrthoNormalize v2.y", b.y, 1)
local fv = r.Vector3ToFloatV({x = 1, y = 2, z = 3})
T.assert_eq("Vector3ToFloatV size", #fv, 3); near("Vector3ToFloatV[3]", fv[3], 3)

-- Matrix
local id = r.MatrixIdentity()
near("MatrixIdentity m0", id.m0, 1); near("MatrixIdentity m5", id.m5, 1); near("MatrixIdentity m1", id.m1, 0)
near("MatrixDeterminant identity", r.MatrixDeterminant(id), 1)
local m = r.MatrixMultiply(r.MatrixTranslate(1, 2, 3), r.MatrixScale(2, 2, 2))
local t, q, s = r.MatrixDecompose(m)
near("MatrixDecompose translation.x", t.x, 2); near("MatrixDecompose translation.z", t.z, 6)
near("MatrixDecompose scale.y", s.y, 2)
near("MatrixDecompose rotation.w", math.abs(q.w), 1)
T.assert_eq("MatrixToFloatV size", #r.MatrixToFloatV(m), 16)
local persp = r.MatrixPerspective(math.rad(60), 16 / 9, 0.1, 100)
near("MatrixPerspective m11", persp.m11, -1)

-- Quaternion
local qa = r.QuaternionFromAxisAngle({x = 0, y = 1, z = 0}, math.pi / 2)
local axis, angle = r.QuaternionToAxisAngle(qa)
near("QuaternionToAxisAngle axis.y", axis.y, 1); near("QuaternionToAxisAngle angle", angle, math.pi / 2)
local qi = r.QuaternionIdentity(); near("QuaternionIdentity w", qi.w, 1)
local prod = r.QuaternionMultiply(qi, qa); near("QuaternionMultiply identity", prod.y, qa.y)
local rotated = r.Vector3RotateByQuaternion({x = 1, y = 0, z = 0}, qa)
near("Vector3RotateByQuaternion z", rotated.z, -1)

-- Argument validation
T.assert_false("Vector2Add rejects non-table", (pcall(r.Vector2Add, 1, 2)))
T.assert_false("Clamp rejects string", (pcall(r.Clamp, "a", 0, 1)))
